SourceCode.Declaration:
public class GUPBasePriceCalcUpdateItem
{
    private NoYes                       purchPriceTransfer;
    private NoYes                       salesPriceTransfer;
    private NoYes                       costPriceTransfer;

    private GUPBasePriceVersionId       basePriceVersionId;
    private TransDate                   calcDate;

    private GUPItemBasePriceCalcTable   itemBasePriceCalcTableTmp;

}

Method.Source:
protected boolean allParamEmpty()
{
    // all parameters are empty
    if (!purchPriceTransfer && !costPriceTransfer && !salesPriceTransfer)
    {
        return true;
    }

    return false;
}

public void initParameters(
    NoYes                       _purchPriceTransfer,
    NoYes                       _salesPriceTransfer,
    NoYes                       _costPriceTransfer,
    GUPBasePriceVersionId       _basePriceVersionId,
    TransDate                   _calcDate)
{
    this.parmPurchPriceTransfer(_purchPriceTransfer);
    this.parmSalesPriceTransfer(_salesPriceTransfer);
    this.parmCostPriceTransfer(_costPriceTransfer);
    this.parmBasePriceVersionId(_basePriceVersionId);
    this.parmCalcDate(_calcDate);
}

public TransDate parmCalcDate(TransDate _calcDate = calcDate)
{
    calcDate = _calcDate;
    return calcDate;
}

public GUPBasePriceVersionId parmBasePriceVersionId(GUPBasePriceVersionId _basePriceVersionId = basePriceVersionId)
{
    basePriceVersionId = _basePriceVersionId;
    return basePriceVersionId;
}

public NoYes parmPurchPriceTransfer(NoYes _purchPriceTransfer = purchPriceTransfer)
{
    purchPriceTransfer = _purchPriceTransfer;
    return purchPriceTransfer;
}

public NoYes parmSalesPriceTransfer(NoYes _salesPriceTransfer = salesPriceTransfer)
{
    salesPriceTransfer = _salesPriceTransfer;
    return salesPriceTransfer;
}

public NoYes parmCostPriceTransfer(NoYes _costPriceTransfer = costPriceTransfer)
{
    costPriceTransfer = _costPriceTransfer;
    return costPriceTransfer;
}

public void run()
{
    #OCCRetryCount
    InventTable inventTable;
    setprefix(GUPBasePriceCalcUpdateItem::description());

    try
    {
        if (!this.validate() || this.allParamEmpty())
        {
            return;
        }

        ttsbegin;

        while select itemBasePriceCalcTableTmp
        {
            inventTable = InventTable::find(itemBasePriceCalcTableTmp.ItemId);

            if (purchPriceTransfer)
            {
                this.removeItemBasePrice(GUPBasePriceType::BasePricePurchase);
                this.updateItemBasePrice(inventTable, GUPBasePriceType::BasePricePurchase);
            }

            if (salesPriceTransfer)
            {
                this.removeItemBasePrice(GUPBasePriceType::BasePriceSales);
                this.updateItemBasePrice(inventTable, GUPBasePriceType::BasePriceSales);
            }

            if (costPriceTransfer)
            {
                this.removeItemBasePrice(GUPBasePriceType::BasePriceInventoryCost);
                this.updateItemBasePrice(inventTable, GUPBasePriceType::BasePriceInventoryCost);
            }
        }

        ttscommit;
    }
    catch (Exception::Deadlock)
    {
        retry;
    }
    catch (Exception::UpdateConflict)
    {
        if (appl.ttsLevel() == 0)
        {
            if (xSession::currentRetryCount() >= #RetryNum)
            {
                throw Exception::UpdateConflictNotRecovered;
            }
            else
            {
                retry;
            }
        }
        else
        {
            throw Exception::UpdateConflict;
        }
    }
    catch (Exception::Error)
    {
        throw error("@SYS18447");
    }
}

protected boolean validate(Object _calledFrom = null)
{
    // no calculation data for transfer
    if (!itemBasePriceCalcTableTmp)
    {
        return checkFailed("@SYS95181");
    }

    return true;
}

private void updateItemBasePrice(InventTable _inventTable , GUPBasePriceType _basePriceType)
{
    GUPItemBasePriceSim         itemBasePriceSim;
    GUPItemBasePriceCalcTrans   itemBasePriceCalcTrans;
    PriceConvertFactory         priceConvertFactory;
    PriceConvert                priceConvert;
    UnitOfMeasureSymbol         unitOfMeasure;

    while select minof(CalculatedPrice) from itemBasePriceCalcTrans
        group by FromDate, ToDate, CreatedDateTime desc
            where itemBasePriceCalcTrans.PriceCalcId == itemBasePriceCalcTableTmp.PriceCalcId &&
                  itemBasePriceCalcTrans.FinalPrice  == NoYes::Yes &&
                  itemBasePriceCalcTrans.PriceType   == _basePriceType
    {
        if (itemBasePriceCalcTrans)
        {
            itemBasePriceSim.initFromCalcTable(itemBasePriceCalcTableTmp);

            priceConvertFactory = PriceConvertFactory::newItemPrice(_inventTable.ItemId,
                                                             itemBasePriceCalcTableTmp.UnitId,
                                                             itemBasePriceCalcTrans.CalculatedPrice,
                                                             itemBasePriceCalcTableTmp.PriceUnit,
                                                             0,
                                                             1,
                                                             "");

            unitOfMeasure = this.getNewUnitId(_inventTable.ItemId, _basePriceType);
            priceConvertFactory.parmNewUnitId(unitOfMeasure);
            priceConvert = priceConvertFactory.priceConvert();

            itemBasePriceSim.PriceType   = _basePriceType;
            itemBasePriceSim.FromDate    = itemBasePriceCalcTrans.FromDate;
            itemBasePriceSim.ToDate      = itemBasePriceCalcTrans.ToDate;
            itemBasePriceSim.PriceQty    = priceConvert.parmPriceQty();
            itemBasePriceSim.Price       = itemBasePriceCalcTrans.CalculatedPrice;
            itemBasePriceSim.UnitId      = unitOfMeasure;
            itemBasePriceSim.PriceCalcId = itemBasePriceCalcTableTmp.PriceCalcId;
            itemBasePriceSim.Calculated  = NoYes::Yes;

            itemBasePriceSim.insert();
        }
    }       
}

private UnitOfMeasureSymbol getNewUnitId(ItemId _itemId, GUPBasePriceType _priceType)
{
    UnitOfMeasureSymbol     unitOfMeasureSymbol;
    InventTable             inventTable = InventTable::find(_itemId);

    switch (_priceType)
    {
        case GUPBasePriceType::BasePriceInventoryCost :
            unitOfMeasureSymbol = inventTable.inventUnitId();
            break;

        case GUPBasePriceType::BasePricePurchase :
            unitOfMeasureSymbol = inventTable.purchUnitId();
            break;

        case GUPBasePriceType::BasePriceSales :
            unitOfMeasureSymbol = inventTable.salesUnitId();
            break;
    }

    return unitOfMeasureSymbol;
}

private void removeItemBasePrice(GUPBasePriceType _basePriceType)
{
    GUPItemBasePriceSim         itemBasePriceSim;
    GUPItemBasePriceCalcTrans   itemBasePriceCalcTrans;

    delete_from itemBasePriceSim
        where itemBasePriceSim.ItemId == itemBasePriceCalcTableTmp.ItemId
            && itemBasePriceSim.VersionId    == basePriceVersionId
            && itemBasePriceSim.PriceType == _basePriceType
            && itemBasePriceSim.UnitId == itemBasePriceCalcTableTmp.UnitId
            && itemBasePriceSim.InventDimId == itemBasePriceCalcTableTmp.InventDimId;
}

private void updateItemBasePriceSim(GUPItemBasePriceSim itemBasePriceSim, GUPItemBasePriceCalcTrans _itemBasePriceCalcTrans)
{
    itemBasePriceSim.PriceCalcId = _itemBasePriceCalcTrans.PriceCalcId;
    itemBasePriceSim.Price = _itemBasePriceCalcTrans.CalculatedPrice;
    itemBasePriceSim.update();
}

static GUPBasePriceCalcUpdateItem construct()
{
    GUPBasePriceCalcUpdateItem   basePriceCalcUpdateItem;

    basePriceCalcUpdateItem = new GUPBasePriceCalcUpdateItem();

    return basePriceCalcUpdateItem;
}
